import packs from "./packs.generated.json"

// rv's shipped packs, generated by scripts/sync-packs.mjs. Safe for client bundles.

export type Pack = { id: string; name: string; category: string; defaultOn: boolean }

export const PACKS: Pack[] = packs
export const CORE_PACKS = PACKS.filter((p) => p.defaultOn).map((p) => p.id)
